entries./**\n * @brief Evaluate an esp_err_t exp:
/**
 * @brief 计算 esp_err_t 表达式，发生错误时执行清理操作并返回错误码。
 *
 * 对 @p x 求值一次，并将结果保存在局部变量 `err_rc_` 中。
 * 如果结果不为 ESP_OK，该宏将：
 *   - 执行 `__VA_ARGS__` 中传入的代码（例如清理函数或日志打印），
 *   - 从当前函数返回 `err_rc_`。
 * 清理代码中可以直接使用 `err_rc_`。
 *
 * 示例：
 * @code{c}
 * esp_err_t initialize_device(void)
 * {
 *     // 简单场景：单个清理操作
 *     ESP_RETURN_ON_ERROR_CLEANUP(open_device("/dev/adc0"), close_device());
 *
 *     // 多个清理操作
 *     ESP_RETURN_ON_ERROR_CLEANUP(
 *         allocate_buffer(4096),
 *         free_buffer(),
 *         close_device(),
 *         printf("Failed to initialize sensor: %s\n", esp_err_to_name(err_rc_))
 *     );
 *
 *     // 包含条件逻辑和 ESP_LOG 日志输出的复杂清理操作
 *     ESP_RETURN_ON_ERROR_CLEANUP(
 *         calibrate_sensor(),
 *         do {
 *             if (err_rc_ == ESP_ERR_INVALID_STATE) {
 *                ESP_LOGE(TAG, "Sensor in invalid state during calibration");}
 *             }
 *             free_buffer();
 *             close_device();
 *             ESP_LOGE(TAG, "Drop connection");
 *         } while (0)
 *     );
 *
 *     return ESP_OK;
 * }
 * @endcode
 */
